// The repo tidy-up, as a composable pack: the PR/branch/issue sweep the repo's own
// scheduler runs, contributed the same way any pack contributes checks and skills.
// Declaring tidy-repo puts its scheduled task on that repo's schedule; removing it
// is a durable opt-out (baselining never re-adds it — see the tidy-repo-seed
// migration).
//
// A declared pack (no detect fingerprint): --init seeds it into every new repo's
// declaration, and the one-time tidy-repo-seed migration seeds the existing fleet.
// It carries no conformance checks — its work is the scheduled task, not checks.
//
// One task per dimension — tidy-issues (daily, acts), tidy-prs and tidy-branches
// (weekly, assess-only) — each delegating its per-object verdict to a single-object
// skill and reconciling its OWN standing tracker. Three narrow tasks, not one wide
// one: each has its own trigger and scope, none depends on another's result, so
// there is no ordering barrier and a dimension with nothing to do stays silent.
export default {
  id: 'tidy-repo',
  version: '60820.1',
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'housekeeping of open issues, pull requests and branches in one repo — triage verdicts, standing trackers, assess-vs-act policy',
    excludes: 'extracting lessons into packs — that is claudinite-growth; cross-repo fleet sweeps are claudinite-fleet-sheepdog',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  worldRules: [],
  // The pack's scheduled tasks live in this pack's own `tasks/<id>/`, discovered by
  // the scheduler's filesystem scan (engine/scheduler/discover.mjs), not declared here.
  //
  // The single-object worker skills those workers apply live under this pack's own
  // skills/ and mount wherever tidy-repo is declared.
  skills: [
    'single-branch-status',
    'single-issue-triage',
    'single-pr-status',
  ],
};
=== basics ===
import referenceIntegrity from './reference-integrity.mjs';
import markdownLinkLabels from './markdown-link-labels.mjs';
import filePlacement from './file-placement.mjs';
import sharedConstants from './shared-constants.mjs';
import declaredCheckMessages from './declared-check-messages.mjs';

// The baseline pack: cross-project working discipline, the task lifecycle, and
// the general engineering skills. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly update
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
export default {
  id: 'basics',
  // A migration record's declared `version` must be ≤ this number, and this number must
  // MOVE for that record to reach a member already at the previous one:
  // `migrationApplies` is `want > have` against the stamped version, and what gets
  // stamped is this manifest's number — so a record declaring a version above it would
  // re-apply every cycle, forever, draining never.
  version: '60821.4',
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; git procedure and GitHub Actions workflow or platform behaviour — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // `core` is required rather than assumed: this pack is declared everywhere, so
  // the closure is what puts Claudinite's own rules in front of every session, and
  // `barriers` arrives with it. git-github carries the git/GitHub side of the task
  // lifecycle (#385).
  requires: ['claudinite-lifecycle', 'git-github'],
  // Rules that audit the repo as it stands, whatever this session did.
  // warning-suppression and rules-line-length are declared checks in this
  // pack's declared-checks.json, discovered structurally beside these.
  worldRules: [
    markdownLinkLabels,
    declaredCheckMessages,
    filePlacement,
    sharedConstants,
  ],
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation. task-lifecycle and squash-merge-history
  // are declared checks carrying scope: "work", discovered structurally beside
  // these.
  workRules: [
    referenceIntegrity,
  ],
  // The baseline skills — general engineering practice every project's work
  // can call for, whatever its technology — bundled under skills/ in this pack's
  // own tree and mounted wherever basics is declared (which --init seeds
  // everywhere). When one stops being a baseline activity, move its directory to
  // the pack whose projects need it and move this line with it (#385 moved the
  // git/GitHub and Claudinite-lifecycle skills out).
  //
  // `task-janitor` and `ci-performance` are this pack's scheduled tasks,
  // discovered by the scheduler's filesystem scan (engine/scheduler/discover.mjs)
  // rather than declared here.
  skills: [
    'authoring-agent-docs',
    'bug-investigation',
    'do-later',
    'ci-performance-evaluation',
    'file-placement',
    'repo-text-sweeps',
    'verify-in-production',
    'writing-migration-plans',
    'writing-tests',
  ],
};
=== node ===
import earnEachDependency from './earn-each-dependency.mjs';

// Fingerprint: a package.json at the repo root OR one directory down (a
// monorepo's functions/ or server/ dir) — but never deeper, so a package.json
// in a nested fixture/example tree can't trip detection. (The jsdom gotchas in
// RULES.md stay prose — runtime divergence with no artifact signature.)
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  id: 'node',
  version: '60820.1',
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'conventions for a Node/npm project — module resolution, ESM vs CJS, dependency justification, jsdom test divergences',
    excludes: 'browser-runtime API behaviour — that is html or web-speech; Python packaging is python',
  },
  badge: 'badge.svg',
  marker: 'package.json (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'package.json'),
  prose: 'RULES.md',
  workRules: [earnEachDependency],
  // The Node runtime ships in the base image, but a repo's (often uncommitted,
  // devDependency) modules don't — so `npm test`/build would trigger a
  // confusing mid-session install. Install them at environment-image build. The
  // package.json location varies per repo, so it's a per-project param: set
  // `dirs` in the node pack entry's `config` in .claudinite-checks.json
  // (default: repo root). A
  // cloud setup script starts in the checkout's PARENT, so env.mjs runs this
  // from the checkout — the `cd "$d"` is relative to it.
  env: {
    label: 'Node dependencies (npm ci)',
    setup: (p) =>
      (p.dirs?.length ? p.dirs : ['.'])
        .map((d) => `( cd "${d}" && npm ci ) || true`)
        .join('\n'),
    probe: (p) =>
      (p.dirs?.length ? p.dirs : ['.'])
        .map((d) => `[ -d "${d}/node_modules" ]`)
        .join(' && '),
  },
};

