      continue;
    }
    if (!mod || typeof mod.id !== 'string') {
      errors.push({
        what: `the pack in ${rel} has no string "id" default export`,
        fix: 'export default { id: "<name>", ... } from its pack.mjs',
        dir: packDir,
      });
      continue;
    }
