1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
4	import { join, dirname } from 'node:path';
5	import { tmpdir } from 'node:os';
6	import { packConventions, applyPackConventions, bundledSkillDirs } from '../../engine/pack_loader/pack-conventions.mjs';
7	import { discoverPacks } from '../../engine/pack_loader/pack-registry.mjs';
8	import { removeTree } from '../../engine/remove-tree.mjs';
9	
10	// A pack directory built from a file map, so each case says only what it is about.
11	function packDir(files) {
12	  const root = mkdtempSync(join(tmpdir(), 'claudinite-conventions-'));
13	  for (const [rel, text] of Object.entries(files)) {
14	    mkdirSync(join(root, dirname(rel)), { recursive: true });
15	    writeFileSync(join(root, rel), text);
16	  }
17	  return root;
18	}
19	
20	test('the tree answers for id, prose, badge and skills', () => {
21	  const dir = packDir({
22	    'pack.mjs': 'export default {};\n',
23	    'RULES.md': '# rules\n',
24	    'badge.svg': '<svg/>\n',
25	    'skills/alpha/SKILL.md': '# alpha\n',
26	    'skills/beta/SKILL.md': '# beta\n',
27	  });
28	  try {
29	    assert.deepEqual(packConventions(dir, 'demo'), {
30	      id: 'demo',
31	      skills: ['alpha', 'beta'],
32	      prose: 'RULES.md',
33	      badge: 'badge.svg',
34	    });
35	  } finally { removeTree(dir); }
36	});
37	
38	test('a file that is not there contributes no field at all', () => {
39	  const dir = packDir({ 'pack.mjs': 'export default {};\n' });
40	  try {
41	    const c = packConventions(dir, 'bare');
42	    assert.deepEqual(c, { id: 'bare', skills: [] });
43	    assert.equal('prose' in c, false);
44	    assert.equal('badge' in c, false);
45	  } finally { removeTree(dir); }
46	});
47	
48	// A skill directory may carry only a skill's checks. `bundledSkillDirs` answers
49	// what the pack BUNDLES; the mount (bundledSkillSources) is what additionally
50	// insists on a SKILL.md before a session can load one.
51	test('a skills/ subdirectory counts whether or not it carries a SKILL.md', () => {
52	  const dir = packDir({
53	    'pack.mjs': 'export default {};\n',
54	    'skills/loadable/SKILL.md': '# s\n',
55	    'skills/checks-only/declared-checks.json': '[]\n',
56	  });
57	  try {
58	    assert.deepEqual(bundledSkillDirs(dir), ['checks-only', 'loadable']);
59	  } finally { removeTree(dir); }
60	});
61	
62	test('a declared field overrides the tree, an explicit null included', () => {
63	  const dir = packDir({
64	    'pack.mjs': 'export default {};\n',
65	    'RULES.md': '# rules\n',
66	    'badge.svg': '<svg/>\n',
67	    'skills/withheld/SKILL.md': '# s\n',
68	    'skills/kept/SKILL.md': '# s\n',
69	  });
70	  try {
71	    const merged = applyPackConventions({ id: 'other', prose: null, skills: ['kept'] }, dir, 'demo');
72	    assert.equal(merged.id, 'other');
73	    assert.equal(merged.prose, null);
74	    assert.deepEqual(merged.skills, ['kept']);
75	    // Undeclared still falls through.
76	    assert.equal(merged.badge, 'badge.svg');
77	  } finally { removeTree(dir); }
78	});
79	
80	test('a non-object export is handed back untouched — the spec is what reports it', () => {
81	  const dir = packDir({ 'pack.mjs': 'export default {};\n' });
82	  try {
83	    for (const bad of [null, undefined, 'nope', [1, 2]]) {
84	      assert.deepEqual(applyPackConventions(bad, dir, 'demo'), bad);
85	    }
86	  } finally { removeTree(dir); }
87	});
