89	// The end-to-end statement: a manifest that declares none of the four still loads
90	// with all four filled in, and a local pack gets the same treatment as a canon one.
91	test('discoverPacks: a manifest declaring none of the four loads with all four', async () => {
92	  const root = mkdtempSync(join(tmpdir(), 'claudinite-conv-local-'));
93	  const dir = join(root, '.claudinite', 'local', 'packs', 'proj');
94	  mkdirSync(join(dir, 'skills', 'doit'), { recursive: true });
95	  writeFileSync(join(dir, 'skills', 'doit', 'SKILL.md'), '# doit\n');
96	  writeFileSync(join(dir, 'RULES.md'), '# proj\n');
97	  writeFileSync(join(dir, 'badge.svg'), '<svg/>\n');
98	  writeFileSync(join(dir, 'pack.mjs'),
