100	  try {
101	    const { packs, errors } = await discoverPacks({ localRoot: root });
102	    assert.deepEqual(errors, []);
103	    const proj = packs.find((p) => p.id === 'proj');
104	    assert.ok(proj, 'the pack loaded with the directory name as its id');
105	    assert.equal(proj.prose, 'RULES.md');
106	    assert.equal(proj.badge, 'badge.svg');
107	    assert.deepEqual(proj.skills, ['doit']);
108	  } finally { removeTree(root); }
