"""Rewrite ES module specifiers across a set of file moves.

Only real import/export STATEMENTS are touched. A statement begins on a line
whose first token is `import` or `export` and runs to the line that closes it, so
a multi-line `import {\n  a,\n} from './x.mjs';` is one unit — and nothing inside
an object literal, an array or a quoted string is ever a candidate.

That boundary is the whole point. Test fixtures embed import statements as string
CONTENT (`'extension/a.js': "import x from '../../server/db.js'"`), describing a
fixture repo's layout rather than this one's. A rewriter that matched `from '...'`
anywhere retargets those to real paths in this tree: the fixture stops describing
what the test says it describes, every path still resolves, and nothing goes red.
"""
import os, re

OPENS = re.compile(r"^\s*(?:import|export)\b")
SPEC = re.compile(r"""(['"])(\.{1,2}/[^'"]+)\1""")
AWAIT_LINE = re.compile(r"""await\s+import\s*\(\s*(['"])(\.{1,2}/[^'"]+)\1""")


def _statement_lines(lines):
    """Yield (index, in_statement) for each line, pairing multi-line imports."""
    open_stmt = False
    for i, line in enumerate(lines):
        if not open_stmt and OPENS.match(line):
            open_stmt = True
        if open_stmt:
            yield i, True
            if line.rstrip().endswith(';') or SPEC.search(line):
                open_stmt = False
        else:
            yield i, False


def rewrite(text, resolve_dir, emit_dir, moves):
    """moves: {old repo-relative path: new repo-relative path}."""
    def retarget(spec):
        target = os.path.normpath(os.path.join(resolve_dir, spec))
        target = moves.get(target, target)
        rel = os.path.relpath(target, emit_dir)
        return rel if rel.startswith('.') else './' + rel

    def sub(m):
        return m.group(1) + retarget(m.group(2)) + m.group(1)

    lines = text.split('\n')
    for i, in_stmt in _statement_lines(lines):
        if in_stmt:
            lines[i] = SPEC.sub(sub, lines[i])
        else:
            lines[i] = AWAIT_LINE.sub(lambda m: m.group(0)[:m.start(2) - m.start(0)] + retarget(m.group(2)) + m.group(0)[m.end(2) - m.start(0):], lines[i])
    return '\n'.join(lines)
