import re, os, subprocess
# Every relative markdown link in the repo that no longer resolves, so this is
# swept once rather than one Stop-hook finding at a time.
LINK=re.compile(r"\]\((?!https?:|#|mailto:)([^)#]+)")
bad=[]
for f in subprocess.run(['git','ls-files','*.md'],capture_output=True,text=True).stdout.split():
    d=os.path.dirname(f)
    for i,line in enumerate(open(f).read().split('\n'),1):
        for m in LINK.finditer(line):
            t=os.path.normpath(os.path.join(d, m.group(1)))
            if not os.path.exists(t): bad.append((f,i,m.group(1),t))
print(len(bad),'dangling relative links')
for f,i,l,t in bad: print(f'  {f}:{i}  {l}')
